#!/usr/bin/env python3
import hashlib
def h(p):
    return hashlib.sha256(open(p, "rb").read()).hexdigest()
ref = dict(l.split() for l in open("hashes.txt"))
ref = {v: k for k, v in ref.items()}
bad = []
for f in ("evidence_A.dd", "evidence_B.dd"):
    got = h(f)
    ok = got in ref
    print("%-16s %s  %s" % (f, got[:16], "OK" if ok else "MISMATCH"))
    if not ok:
        bad.append(f)
print("tampered:", bad)
if bad:
    print("verdict: nto{3v1d3nc3_t4mp3r_d3t3ct3d}")
